# The sienna palette. Colour values live in R/palette-sienna-data.R, generated by
# data-raw/palette-sienna.R.

sienna_l <- 63
sienna_c <- 60
sienna_harmony <- 0.35

#' Sienna colours
#'
#' The 24 sienna swatches. `sienna_colours` holds the original swatches for
#' logos, tables and one-off accents. `sienna_colours_harmonised` holds the
#' same hues with lightness and chroma pulled towards L 63, C 60; plots use
#' these. `sienna_gradients`, `sienna_diverging` and `sienna_ramps` hold the
#' 9-stop sequential, diverging and single-hue palettes.
#'
#' @format Named character vectors of hex codes (`sienna_colours`,
#'   `sienna_colours_harmonised`) and named lists of 9 hex codes each
#'   (`sienna_gradients`, `sienna_diverging`, `sienna_ramps`).
#' @name sienna_colours
#' @aliases sienna_colours_harmonised sienna_gradients sienna_diverging sienna_ramps
#' @export sienna_colours sienna_colours_harmonised sienna_gradients sienna_diverging sienna_ramps
#' @examples
#' sienna_colours[["teal"]]
#' sienna_colours_harmonised[["teal"]]
#' names(sienna_gradients)
NULL

#' Sienna discrete palette
#'
#' Drop-in replacement for [scales::pal_hue()]. Spaces `n` target hues evenly
#' from `h_start` and snaps each to the nearest unused hue of the 13-hue sienna
#' wheel, so group k lands on roughly the same hue as in ggplot2's default.
#' Above 13 groups it falls back to evenly spaced hues at sienna lightness and
#' chroma.
#'
#' @param h_start Starting hue in degrees. 18 is the palette's red; `scales::pal_hue()`
#'   starts at 15.
#' @param direction `1` for increasing hue, `-1` for decreasing.
#' @param harmonise If `TRUE`, return harmonised colours; if `FALSE`, the
#'   original swatches for the same selection.
#' @return A function of `n` returning `n` hex codes.
#' @export
#' @examples
#' sienna_pal()(5)
#' sienna_pal(h_start = 145, direction = -1)(3)
sienna_pal <- function(h_start = 18, direction = 1, harmonise = TRUE) {
  force(h_start)
  force(direction)
  force(harmonise)
  function(n) {
    targets <- (h_start + direction * 360 * (seq_len(n) - 1) / n) %% 360
    if (n > length(sienna_wheel_hues)) {
      return(sienna_hcl(targets, sienna_c, sienna_l))
    }
    key <- sienna_snap(targets, sienna_wheel_hues)
    source <- if (harmonise) sienna_colours_harmonised else sienna_colours
    unname(source[key])
  }
}

sienna_snap <- function(targets, wheel) {
  d <- abs(outer(targets, unname(wheel), \(a, b) (a - b + 180) %% 360 - 180))
  pick <- integer(length(targets))
  for (i in seq_along(targets)) {
    m <- which(d == min(d), arr.ind = TRUE)[1, ]
    pick[m[1]] <- m[2]
    d[m[1], ] <- Inf
    d[, m[2]] <- Inf
  }
  names(wheel)[pick]
}

#' Sienna colours from HCL coordinates
#'
#' Converts hue, chroma and luminance (polar CIELUV, as in [grDevices::hcl()])
#' to hex. Out-of-gamut colours have their chroma lowered in steps of 0.5
#' until they fit, instead of returning `NA`.
#'
#' @param h Hue in degrees.
#' @param c Chroma.
#' @param l Luminance, 0 to 100.
#' @return A character vector of hex codes.
#' @export
#' @examples
#' sienna_hcl(h = 200, c = 40, l = 70)
sienna_hcl <- function(h, c, l) {
  n <- max(length(h), length(c), length(l))
  h <- rep_len(h, n) %% 360
  c <- pmax(rep_len(c, n), 0)
  l <- pmin(pmax(rep_len(l, n), 0), 100)
  out <- grDevices::hcl(h, c, l, fixup = FALSE)
  while (anyNA(out)) {
    bad <- is.na(out)
    c[bad] <- pmax(c[bad] - 0.5, 0)
    out[bad] <- grDevices::hcl(h[bad], c[bad], l[bad], fixup = FALSE)
  }
  out
}

#' Harmonise colours to the sienna palette
#'
#' Keeps each colour's hue and pulls its lightness and chroma towards the
#' palette's level, keeping `strength` of the original deviation. This is the pull
#' that produced [sienna_colours_harmonised]. Needs the colorspace package.
#'
#' @param x Hex codes, optionally named.
#' @param l,c Target luminance and chroma.
#' @param strength Share of the original deviation to keep: `0` flattens
#'   fully, `1` leaves the colours untouched.
#' @return Hex codes with the names of `x`.
#' @export
#' @examples
#' if (rlang::is_installed("colorspace")) sienna_harmonise(c(accent = "#FF0066"))
sienna_harmonise <- function(x, l = sienna_l, c = sienna_c, strength = sienna_harmony) {
  rlang::check_installed("colorspace", reason = "to convert hex codes to HCL.")
  hcl <- colorspace::hex2RGB(x) |>
    methods::as("polarLUV") |>
    colorspace::coords()
  sienna_hcl(hcl[, "H"], c + strength * (hcl[, "C"] - c), l + strength * (hcl[, "L"] - l)) |>
    rlang::set_names(names(x))
}

#' Sienna gradients
#'
#' `sienna_gradient()` returns the 9 stops of a sequential, diverging or
#' single-hue palette. `sienna_ramp()` returns the single-hue ramp of one
#' swatch. `sienna_grad_pal()` returns a palette function for values in
#' `[0, 1]`, like [scales::pal_gradient_n()].
#'
#' Sequential gradients run light (low) to dark (high), the opposite of
#' ggplot2's default; `reverse = TRUE` matches ggplot2.
#'
#' @param palette A name from `sienna_gradients`, `sienna_diverging` or
#'   `sienna_colours`.
#' @param colour A name from `sienna_colours`.
#' @param reverse If `TRUE`, reverse the order of the stops.
#' @return `sienna_gradient()` and `sienna_ramp()` return 9 hex codes;
#'   `sienna_grad_pal()` returns a function.
#' @export
#' @examples
#' sienna_gradient("ocean")
#' sienna_ramp("purple")
#' sienna_grad_pal("sunset")(seq(0, 1, length.out = 10))
sienna_gradient <- function(palette = "ocean", reverse = FALSE) {
  cols <- palette_lookup(palette, list(sienna_gradients, sienna_diverging, sienna_ramps))
  if (reverse) rev(cols) else cols
}

#' @rdname sienna_gradient
#' @export
sienna_ramp <- function(colour) {
  palette_lookup(colour, list(sienna_ramps))
}

#' @rdname sienna_gradient
#' @export
sienna_grad_pal <- function(palette = "ocean", reverse = FALSE) {
  scales::pal_gradient_n(sienna_gradient(palette, reverse))
}

#' Sienna scales for ggplot2
#'
#' Drop-in replacements for ggplot2's default colour and fill scales.
#'
#' | ggplot2 default | sienna replacement |
#' |---|---|
#' | `scale_colour_discrete()` | `scale_colour_sienna_d()` |
#' | `scale_fill_continuous()` | `scale_fill_sienna_c("ocean")` |
#' | `scale_fill_binned()` | `scale_fill_sienna_b("ocean")` |
#' | `scale_fill_gradient2(midpoint = m)` | `scale_fill_sienna_div("red_blue", midpoint = m)` |
#'
#' @inheritParams sienna_pal
#' @inheritParams sienna_gradient
#' @param ... Passed to the underlying ggplot2 scale, such as `name`,
#'   `limits`, `breaks` or `na.value`.
#' @param midpoint Data value mapped to the neutral centre.
#' @param aesthetics Aesthetics the scale applies to.
#' @return A ggplot2 scale.
#' @name scale_sienna
#' @examples
#' p <- ggplot2::ggplot(ggplot2::mpg, ggplot2::aes(displ, hwy, colour = class)) +
#'   ggplot2::geom_point()
#' p + scale_colour_sienna_d()
#'
#' ggplot2::ggplot(ggplot2::faithfuld, ggplot2::aes(waiting, eruptions, fill = density)) +
#'   ggplot2::geom_raster() +
#'   scale_fill_sienna_c("teal", reverse = TRUE)
NULL

#' @rdname scale_sienna
#' @export
scale_colour_sienna_d <- function(..., h_start = 18, direction = 1, harmonise = TRUE, aesthetics = "colour") {
  palette_scale_d(aesthetics, sienna_pal(h_start, direction, harmonise), ...)
}

#' @rdname scale_sienna
#' @export
scale_fill_sienna_d <- function(..., h_start = 18, direction = 1, harmonise = TRUE, aesthetics = "fill") {
  palette_scale_d(aesthetics, sienna_pal(h_start, direction, harmonise), ...)
}

#' @rdname scale_sienna
#' @export
scale_colour_sienna_c <- function(palette = "ocean", ..., reverse = FALSE, aesthetics = "colour") {
  palette_scale_c(aesthetics, sienna_gradient(palette, reverse), ...)
}

#' @rdname scale_sienna
#' @export
scale_fill_sienna_c <- function(palette = "ocean", ..., reverse = FALSE, aesthetics = "fill") {
  palette_scale_c(aesthetics, sienna_gradient(palette, reverse), ...)
}

#' @rdname scale_sienna
#' @export
scale_colour_sienna_b <- function(palette = "ocean", ..., reverse = FALSE, aesthetics = "colour") {
  palette_scale_b(aesthetics, sienna_gradient(palette, reverse), ...)
}

#' @rdname scale_sienna
#' @export
scale_fill_sienna_b <- function(palette = "ocean", ..., reverse = FALSE, aesthetics = "fill") {
  palette_scale_b(aesthetics, sienna_gradient(palette, reverse), ...)
}

#' @rdname scale_sienna
#' @export
scale_colour_sienna_div <- function(palette = "red_blue", ..., midpoint = 0, reverse = FALSE, aesthetics = "colour") {
  palette_scale_div(aesthetics, sienna_gradient(palette, reverse), ..., midpoint = midpoint)
}

#' @rdname scale_sienna
#' @export
scale_fill_sienna_div <- function(palette = "red_blue", ..., midpoint = 0, reverse = FALSE, aesthetics = "fill") {
  palette_scale_div(aesthetics, sienna_gradient(palette, reverse), ..., midpoint = midpoint)
}

#' @rdname scale_sienna
#' @export
scale_color_sienna_d <- scale_colour_sienna_d

#' @rdname scale_sienna
#' @export
scale_color_sienna_c <- scale_colour_sienna_c

#' @rdname scale_sienna
#' @export
scale_color_sienna_b <- scale_colour_sienna_b

#' @rdname scale_sienna
#' @export
scale_color_sienna_div <- scale_colour_sienna_div

#' Make sienna the default ggplot2 palette
#'
#' Sets ggplot2's `ggplot2.discrete.*`, `ggplot2.continuous.*` and
#' `ggplot2.binned.*` options, so every plot uses sienna without a `scale_*()`
#' call. [reset_ggplot2_palette()] switches back.
#'
#' @inheritParams sienna_pal
#' @param continuous Palette for continuous and binned scales.
#' @return The previous option values, invisibly.
#' @export
#' @examples
#' use_sienna_palette(continuous = "ocean")
#' ggplot2::ggplot(ggplot2::mpg, ggplot2::aes(displ, hwy, colour = class)) +
#'   ggplot2::geom_point()
#' reset_ggplot2_palette()
use_sienna_palette <- function(h_start = 18, harmonise = TRUE, continuous = "ocean") {
  sienna_gradient(continuous)
  palette_set_options(
    colour_d = \(...) scale_colour_sienna_d(..., h_start = h_start, harmonise = harmonise),
    fill_d   = \(...) scale_fill_sienna_d(..., h_start = h_start, harmonise = harmonise),
    colour_c = \(...) scale_colour_sienna_c(continuous, ...),
    fill_c   = \(...) scale_fill_sienna_c(continuous, ...),
    colour_b = \(...) scale_colour_sienna_b(continuous, ...),
    fill_b   = \(...) scale_fill_sienna_b(continuous, ...)
  )
}
